import sys
from collections import deque, defaultdict

def bfs_tree(start, n, roads):
    tree = defaultdict(list)
    for u, v in roads:
        tree[u].append(v)
        tree[v].append(u)

    parent = {start: None}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if neighbor not in parent:
                parent[neighbor] = node
                queue.append(neighbor)
    return parent

def find_min_distance_to_attacked_cities(start, parent, attacked_cities):
    visited = set()
    queue = deque([(start, 0)])
    min_distance = float('inf')
    teleport_city = start

    while queue:
        node, dist = queue.popleft()
        if node in visited:
            continue
        visited.add(node)

        if node in attacked_cities:
            if dist < min_distance:
                min_distance = dist
                teleport_city = node
            elif dist == min_distance:
                teleport_city = min(teleport_city, node)

        for neighbor in parent:
            if parent[neighbor] == node:
                queue.append((neighbor, dist + 1))

    return teleport_city, min_distance

def super_m_teleportation(n, m, roads, attacked_cities):
    roads = [(u, v) for u, v in roads]

    min_time = float('inf')
    best_teleport_city = None

    for start_city in range(1, n + 1):
        parent_tree = bfs_tree(start_city, n, roads)
        teleport_city, min_distance = find_min_distance_to_attacked_cities(start_city, parent_tree, attacked_cities)

        total_time = min_distance + len(attacked_cities)
        if total_time < min_time:
            min_time = total_time
            best_teleport_city = teleport_city
        elif total_time == min_time:
            best_teleport_city = min(best_teleport_city, teleport_city)

    return best_teleport_city, min_time

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    roads = []
    index = 2
    for _ in range(n - 1):
        u = int(data[index])
        v = int(data[index + 1])
        roads.append((u, v))
        index += 2

    attacked_cities = set()
    for _ in range(m):
        attacked_cities.add(int(data[index]))
        index += 1

    teleport_city, min_time = super_m_teleportation(n, m, roads, attacked_cities)
    print(teleport_city)
    print(min_time)

if __name__ == "__main__":
    main()
